// Copies icons and overlays out of the immutable handoff and generates typed registries.
// Backgrounds come from scripts/optimize-backgrounds.mjs.
// Run with `npm run generate:assets`. Never edit src/design/generated by hand.
import { cpSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, join } from 'node:path';
import sharp from 'sharp';

const handoff = 'product-handoff/assets';
const generated = 'src/design/generated';
mkdirSync(generated, { recursive: true });

for (const dir of ['icons', 'overlays']) {
  cpSync(join(handoff, dir), join('assets', dir), { recursive: true });
}

const banner = '// GENERATED by scripts/generate-design-assets.mjs. Do not edit.\n';
const manifest = JSON.parse(readFileSync('product-handoff/data/screen-manifest.json', 'utf8'));

const entry = (theme) =>
  manifest.screens
    .map(
      (s) =>
        `    '${s.id}': require('../../../assets/backgrounds/${theme}/${s.background.replace('.png', '.webp')}'),`,
    )
    .join('\n');
// Average colour of each plate, shown while it decodes so a screen is never blank.
const colours = {};
for (const theme of ['day', 'night']) {
  colours[theme] = {};
  for (const s of manifest.screens) {
    const file = `assets/backgrounds/${theme}/${s.background.replace('.png', '.webp')}`;
    const { channels } = await sharp(file).resize(64).stats();
    const [r, g, b] = channels.map(({ mean }) => Math.round(mean));
    colours[theme][s.id] = `rgb(${r},${g},${b})`;
  }
}

writeFileSync(
  join(generated, 'backgrounds.ts'),
  `${banner}/* eslint-disable */\nexport const backgroundSources = {\n  day: {\n${entry('day')}\n  },\n  night: {\n${entry('night')}\n  },\n} as const;\n\nexport const backgroundColours = ${JSON.stringify(colours, null, 2)} as const;\n`,
);

const svgs = (dir) =>
  readdirSync(join(handoff, dir))
    .filter((f) => f.endsWith('.svg'))
    .sort()
    .map((f) => [basename(f, '.svg'), readFileSync(join(handoff, dir, f), 'utf8').trim()]);

const toRecord = (name, pairs) =>
  `export const ${name} = {\n${pairs.map(([k, v]) => `  '${k}': ${JSON.stringify(v)},`).join('\n')}\n} as const;\n`;

// Overlays are drawn at 393x852; a viewBox lets them stretch over any viewport.
const overlays = svgs('overlays').map(([k, v]) => [
  k,
  v.replace('width="393" height="852"', 'viewBox="0 0 393 852" preserveAspectRatio="none"'),
]);

writeFileSync(
  join(generated, 'vectors.ts'),
  `${banner}${toRecord('iconXml', svgs('icons'))}\n${toRecord('overlayXml', overlays)}`,
);
console.log('assets and registries generated');
